-- Additive hardening after 0012 was applied. SQL CHECK treats NULL as success unless explicitly closed.
CREATE FUNCTION document_string_fields(value jsonb, fields text[]) RETURNS boolean LANGUAGE sql IMMUTABLE STRICT AS $$ SELECT coalesce(bool_and(coalesce(jsonb_typeof(value->field)='string',false)),false) FROM unnest(fields) AS field $$;
--> statement-breakpoint
ALTER TABLE documents ADD CONSTRAINT document_snapshot_types CHECK((document_string_fields(snapshot,ARRAY['documentId','actorId','capturedAt','locale']) AND snapshot->'schemaVersion'='1'::jsonb AND snapshot->'sample'='true'::jsonb AND jsonb_typeof(snapshot->'template'->'version')='number' AND jsonb_typeof(snapshot->'outbound'->'version')='string' AND (snapshot->>'capturedAt') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}Z$' AND (snapshot->>'capturedAt')::timestamptz IS NOT NULL) IS TRUE);
ALTER TABLE document_lines ADD CONSTRAINT document_line_types CHECK((jsonb_typeof(snapshot)='object' AND snapshot ?& ARRAY['id','skuId','skuCode','productName','requested','cancelled','remaining','shipped','received','reserved','transit'] AND snapshot-ARRAY['id','skuId','skuCode','productName','requested','cancelled','remaining','shipped','received','reserved','transit']='{}'::jsonb AND document_string_fields(snapshot,ARRAY['id','skuId','skuCode','productName','requested','cancelled','remaining','shipped','received','reserved','transit'])) IS TRUE);
ALTER TABLE document_sources ADD CONSTRAINT document_source_types CHECK((jsonb_typeof(snapshot)='object' AND snapshot ?& ARRAY['lineId','reservationId','shipmentLineId','quantity','consumed','released','received'] AND snapshot-ARRAY['lineId','reservationId','shipmentLineId','quantity','consumed','released','received']='{}'::jsonb AND document_string_fields(snapshot,ARRAY['lineId','quantity','consumed','released','received'])) IS TRUE);
